fn frame(t: i32) {
    let sx: i32 = 100;
    let sy: i32 = 110;
    let sw: i32 = 120;
    let sh: i32 = 56;
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(2);
    let px: i32 = host::display::pointer_x();
    let py: i32 = host::display::pointer_y();
    let mut on: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 && px >= sx && px < sx + sw && py >= sy && py < sy + sh {
        on = 1 - on;
        host::display::state_set(0, on);
    }
    host::display::state_set(2, down);
    let goal: i32 = if on == 1 { sw - 52 } else { 4 };
    let mut k: i32 = host::display::state_get(1);
    let d: i32 = goal - k;
    k = k + d / 4;
    if d > 0 && d / 4 == 0 { k = k + 1; }
    if d < 0 && d / 4 == 0 { k = k - 1; }
    host::display::state_set(1, k);
    host::display::clear(0x101010);
    let track: i32 = if on == 1 { 0x006644 } else { 0x333333 };
    host::display::fill_rect(sx, sy, sw, sh, track);
    host::display::fill_rect(sx + k, sy + 4, 48, sh - 8, 0xf0f0f0);
    if on == 1 {
        host::display::draw_string(sx, sy - 24, "ON", 0x00ff88, 2);
    } else {
        host::display::draw_string(sx, sy - 24, "OFF", 0x808080, 2);
    }
    host::display::present();
}
